export interface CuisineProfile {
  id: string;
  name: string;
  aliases: string[];
  proteins: string[];
  grains: string[];
  vegetables: string[];
  spices: string[];
  herbs: string[];
  techniques: string[];
}

const profile = (input: CuisineProfile) => Object.freeze(input);

