export function getCuisineProfile(value: string) {
  const normalized = value.trim().toLowerCase().replace(/[^a-z]/g, "");
  return Object.values(CuisineProfiles).find((candidate) =>
    [candidate.id, candidate.name, ...candidate.aliases].some((alias) => alias.replace(/[^a-z]/gi, "").toLowerCase() === normalized)
  ) ?? null;
}
